import {ApiFailure} from '@/lib/api/client';
import {
  liveServerOf,
  saveStaticBooking,
  staticAvailability,
  staticCancelBooking,
  staticCatalog,
  staticCreateBooking,
  staticGetBooking,
  staticRescheduleBooking,
  type BusyInterval,
} from '@/lib/demo/static';
import type {ApiAvailabilityResponse, ApiBooking, ApiCreateBookingResponse, ApiCustomer, ApiService, ApiTenant} from '@/types/api';

/**
 * Боевая студия без базы Supabase: каталог берётся из сборки, как у демо, а запись уходит на наш сервер
 * (Cloudflare, src/studio.js в lead-worker). Сервер проверяет свободный бокс, сохраняет запись и пишет
 * владельцу в Telegram или от его группы ВК. В браузере клиента остаётся копия записи и токен для отмены и переноса.
 */

const TOKEN_PREFIX = 'live-token:';
/** Сервер помощника для демо-студий: у боевых — свой адрес из business.json. */
const DEFAULT_SERVER = 'https://detroll-lead.detroll.workers.dev';

export function isLiveStudio(slug: string): boolean {
  return liveServerOf(slug) !== null;
}

interface ServerAnswer {
  ok: boolean;
  error?: string;
  message?: string;
  [key: string]: unknown;
}

async function call(slug: string, path: string, body?: unknown, signal?: AbortSignal, anyStudio = false): Promise<ServerAnswer> {
  const server = liveServerOf(slug) ?? (anyStudio ? DEFAULT_SERVER : null);
  if (!server) throw new ApiFailure('Студия не найдена.', 'not_found', 404);
  let response: Response;
  try {
    response = await fetch(server + path, {
      method: body === undefined ? 'GET' : 'POST',
      headers: body === undefined ? undefined : {'Content-Type': 'application/json'},
      body: body === undefined ? undefined : JSON.stringify(body),
      signal,
    });
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') throw error;
    throw new ApiFailure('Нет связи с сервером записи. Проверьте интернет или позвоните в студию.', 'network', 0);
  }
  let data: ServerAnswer;
  try {
    data = (await response.json()) as ServerAnswer;
  } catch {
    throw new ApiFailure('Сервер записи ответил с ошибкой. Попробуйте ещё раз.', 'server', response.status);
  }
  if (!data.ok) throw new ApiFailure(data.message ?? 'Не удалось выполнить запрос.', data.error ?? 'server', response.status);
  return data;
}

function serverToken(localToken: string | undefined): string {
  try {
    const value = localToken ? localStorage.getItem(TOKEN_PREFIX + localToken) : null;
    if (value) return value;
  } catch {
    /* ниже вернётся ошибка */
  }
  throw new ApiFailure('Запись не найдена на этом устройстве. Позвоните в студию, чтобы изменить её.', 'not_found', 404);
}

export async function liveAvailability(
  slug: string,
  serviceId: string,
  fromDate: string,
  days: number,
  signal?: AbortSignal,
): Promise<ApiAvailabilityResponse> {
  const from = new Date(`${fromDate}T00:00:00Z`).getTime() - 86_400_000;
  const to = from + (days + 2) * 86_400_000;
  const data = await call(
    slug,
    `/studio/busy?slug=${encodeURIComponent(slug)}&from=${new Date(from).toISOString()}&to=${new Date(to).toISOString()}`,
    undefined,
    signal,
  );
  const intervals = (data.busy as BusyInterval[] | undefined) ?? [];
  const bays = Number(data.bays) || 1;
  return staticAvailability(slug, serviceId, fromDate, days, {intervals, bays});
}

export async function liveCreateBooking(
  input: {slug: string; serviceId: string; startAt: string; customer: ApiCustomer},
  signal?: AbortSignal,
): Promise<ApiCreateBookingResponse> {
  const service = staticCatalog(input.slug).services.find((s) => s.id === input.serviceId);
  if (!service) throw new ApiFailure('Услуга не найдена.', 'not_found', 404);
  const data = await call(
    input.slug,
    '/studio/booking',
    {
      slug: input.slug,
      service: service.name,
      price: Math.round(service.priceMinor / 100),
      minutes: service.durationMinutes,
      startAt: input.startAt,
      name: input.customer.name,
      phone: input.customer.phone,
      car: input.customer.car ?? '',
      comment: input.customer.comment ?? '',
    },
    signal,
  );
  const result = staticCreateBooking(input);
  const booking: ApiBooking = {...result.booking, id: typeof data.id === 'string' ? data.id : result.booking.id};
  saveStaticBooking(result.accessToken, booking);
  try {
    if (typeof data.token === 'string') localStorage.setItem(TOKEN_PREFIX + result.accessToken, data.token);
  } catch {
    /* без хранилища отменить запись можно только звонком */
  }
  return {...result, booking};
}

export function liveGetBooking(token: string | undefined): {booking: ApiBooking} {
  return staticGetBooking(token);
}

export async function liveCancelBooking(slug: string, token: string | undefined): Promise<{booking: ApiBooking}> {
  await call(slug, '/studio/cancel', {slug, token: serverToken(token)});
  return staticCancelBooking(token);
}

export async function liveRescheduleBooking(slug: string, token: string | undefined, startAt: string): Promise<{booking: ApiBooking}> {
  await call(slug, '/studio/move', {slug, token: serverToken(token), startAt});
  return staticRescheduleBooking(token, startAt);
}

export interface StudioAssistantReply {
  reply: string;
  /** Точное имя услуги, если клиент хочет записаться: под ответом показываются свободные окна. */
  service: string;
  book: boolean;
}

/** Помощник студии (нейросеть на нашем сервере) отвечает по данным студии со страницы. */
export async function askStudioAssistant(
  slug: string,
  message: string,
  history: {role: 'user' | 'assistant'; content: string}[],
  tenant: ApiTenant,
  services: ApiService[],
): Promise<StudioAssistantReply> {
  const data = await call(
    slug,
    '/studio/assistant',
    {
      slug,
      message,
      history,
      studio: {
        name: tenant.name,
        description: tenant.description,
        address: tenant.address,
        phone: tenant.phone,
        hours: tenant.hoursSummary,
        notes: tenant.infoCards.map((card) => `${card.title}: ${card.body}`),
        services: services.map((s) => ({
          name: s.name,
          price: Math.round(s.priceMinor / 100),
          minutes: s.durationMinutes,
          description: s.description ?? '',
        })),
      },
    },
    undefined,
    true,
  );
  return {
    reply: typeof data.reply === 'string' ? data.reply : '',
    service: typeof data.service === 'string' ? data.service : '',
    book: data.book === true,
  };
}
