import {callFunction} from './client';
import {withDemoMedia} from '@/lib/demo/media';
import {
  hasStaticDemo,
  staticAssistant,
  staticAvailability,
  staticCancelBooking,
  staticCatalog,
  staticCreateBooking,
  staticGetBooking,
  staticRescheduleBooking,
} from '@/lib/demo/static';
import {
  isLiveStudio,
  liveAvailability,
  liveCancelBooking,
  liveCreateBooking,
  liveGetBooking,
  liveRescheduleBooking,
} from '@/lib/demo/live';
import type {
  ApiAssistantReply,
  ApiAvailabilityResponse,
  ApiBooking,
  ApiCreateBookingResponse,
  ApiCustomer,
  ApiService,
  ApiTenant,
  ApiWork,
} from '@/types/api';

export interface CatalogResponse {
  tenant: ApiTenant;
  services: ApiService[];
  works: ApiWork[];
  serverTime: string;
}

export function fetchCatalog(slug: string, signal?: AbortSignal): Promise<CatalogResponse> {
  if (hasStaticDemo(slug)) return Promise.resolve(withDemoMedia(slug, staticCatalog(slug)));
  return callFunction<CatalogResponse>('catalog', {
    body: {slug, demo: demoFlag()},
    method: 'POST',
    signal,
  }).then((data) => withDemoMedia(slug, data));
}

export function fetchAvailability(
  slug: string,
  serviceId: string,
  fromDate: string,
  days: number,
  signal?: AbortSignal,
): Promise<ApiAvailabilityResponse> {
  if (isLiveStudio(slug)) return liveAvailability(slug, serviceId, fromDate, days, signal);
  if (hasStaticDemo(slug)) return Promise.resolve(staticAvailability(slug, serviceId, fromDate, days));
  return callFunction<ApiAvailabilityResponse>('availability', {
    body: {slug, serviceId, fromDate, days, demo: demoFlag()},
    signal,
  });
}

export interface CreateBookingInput {
  slug: string;
  serviceId: string;
  startAt: string;
  customer: ApiCustomer;
  idempotencyKey: string;
  demo: boolean;
}

export function createBooking(input: CreateBookingInput, signal?: AbortSignal): Promise<ApiCreateBookingResponse> {
  if (isLiveStudio(input.slug)) return liveCreateBooking(input, signal);
  if (hasStaticDemo(input.slug)) return Promise.resolve(staticCreateBooking(input));
  return callFunction<ApiCreateBookingResponse>('bookings', {
    body: {action: 'create', ...input},
    signal,
  });
}

export function fetchBookingByToken(slug: string, token: string, signal?: AbortSignal): Promise<{booking: ApiBooking}> {
  if (isLiveStudio(slug)) return Promise.resolve(liveGetBooking(token));
  if (hasStaticDemo(slug)) return Promise.resolve(staticGetBooking(token));
  return callFunction<{booking: ApiBooking}>('bookings', {
    body: {action: 'get', slug},
    bookingToken: token,
    signal,
  });
}

export function cancelBookingByToken(slug: string, token: string, reason: string): Promise<{booking: ApiBooking}> {
  if (isLiveStudio(slug)) return liveCancelBooking(slug, token);
  if (hasStaticDemo(slug)) return Promise.resolve(staticCancelBooking(token));
  return callFunction<{booking: ApiBooking}>('bookings', {
    body: {action: 'cancel', slug, reason},
    bookingToken: token,
  });
}

export function rescheduleBookingByToken(
  slug: string,
  token: string,
  startAt: string,
  idempotencyKey: string,
): Promise<{booking: ApiBooking}> {
  if (isLiveStudio(slug)) return liveRescheduleBooking(slug, token, startAt);
  if (hasStaticDemo(slug)) return Promise.resolve(staticRescheduleBooking(token, startAt));
  return callFunction<{booking: ApiBooking}>('bookings', {
    body: {action: 'reschedule', slug, startAt, idempotencyKey},
    bookingToken: token,
  });
}

export function subscribeReminder(slug: string, token: string, subscription: unknown): Promise<{ok: boolean}> {
  if (hasStaticDemo(slug)) return Promise.resolve({ok: true});
  return callFunction<{ok: boolean}>('bookings', {
    body: {action: 'subscribe-push', slug, subscription},
    bookingToken: token,
  });
}

export interface AssistantQuestion {
  slug: string;
  scope: 'client';
  message: string;
  history: {role: 'user' | 'assistant'; content: string}[];
  accessToken?: string;
}

export function askClientAssistant(input: AssistantQuestion, signal?: AbortSignal): Promise<ApiAssistantReply> {
  if (hasStaticDemo(input.slug)) return Promise.resolve(staticAssistant(input.slug));
  return callFunction<ApiAssistantReply>('assistant', {body: input, signal});
}

export function demoFlag(): boolean {
  return import.meta.env.VITE_APP_ENV !== 'production';
}
